-- GENERATED by `python -m silver.render` from silver/spec.py. Do not edit by hand.
-- Safe to run repeatedly. {db} is the database name.

-- ---- merchants: stream -> MERGE (reference track) ----
CREATE TABLE IF NOT EXISTS {db}.SILVER.silver_merchants_versions (
  merchant_id STRING,
  sequence NUMBER,
  event_id STRING,
  is_deleted BOOLEAN,
  name STRING,
  country STRING,
  vertical STRING,
  risk_status STRING,
  valid_from TIMESTAMP_NTZ,
  loaded_at TIMESTAMP_LTZ,
  source_file STRING,
  source_row NUMBER
) CHANGE_TRACKING = TRUE;

CREATE TABLE IF NOT EXISTS {db}.SILVER.silver_merchants (
  merchant_id STRING,
  name STRING,
  country STRING,
  vertical STRING,
  risk_status STRING,
  is_deleted BOOLEAN,
  last_sequence NUMBER,
  last_event_id STRING,
  last_event_time TIMESTAMP_NTZ
) CHANGE_TRACKING = TRUE;

CREATE TABLE IF NOT EXISTS {db}.QUARANTINE.rejected_merchants (
  event_id STRING,
  entity_id STRING,
  sequence NUMBER,
  reject_reason STRING,
  raw VARIANT,
  source_file STRING,
  source_row NUMBER,
  loaded_at TIMESTAMP_LTZ,
  rejected_at TIMESTAMP_LTZ DEFAULT CURRENT_TIMESTAMP()
);

-- SCD2 history: one row per version, with the end of each version derived from the next one.
-- Deriving valid_to at read time means a late, out-of-order event cannot leave a stale end date.
CREATE OR REPLACE VIEW {db}.SILVER.silver_merchants_history AS
SELECT
  merchant_id, sequence, is_deleted, name, country, vertical, risk_status, valid_from,
  LEAD(valid_from) OVER (PARTITION BY merchant_id ORDER BY sequence) AS valid_to,
  LEAD(valid_from) OVER (PARTITION BY merchant_id ORDER BY sequence) IS NULL AS is_current
FROM {db}.SILVER.silver_merchants_versions;

-- SHOW_INITIAL_ROWS: a stream normally starts empty. Bronze already holds rows when this is first
-- deployed, so the first run must see them too.
CREATE STREAM IF NOT EXISTS {db}.BRONZE.ref_merchants_stream ON TABLE {db}.BRONZE.ref_merchants
  APPEND_ONLY = TRUE SHOW_INITIAL_ROWS = TRUE;

-- One transaction: the stream offset moves only if all three statements commit, so a failed run
-- is retried with the same changes. Every statement reads the same stream snapshot.
CREATE OR REPLACE PROCEDURE {db}.OPS.MERGE_MERCHANTS()
  RETURNS STRING
  LANGUAGE SQL
  EXECUTE AS CALLER
AS
$$
BEGIN
  BEGIN TRANSACTION;

  INSERT INTO {db}.QUARANTINE.rejected_merchants (event_id, entity_id, sequence, reject_reason, raw, source_file, source_row, loaded_at)
  WITH parsed AS (
    SELECT
      IFF(TYPEOF(GET_PATH(raw, 'event_id')) = 'VARCHAR', GET_PATH(raw, 'event_id')::STRING, NULL) AS event_id,
      IFF(TYPEOF(GET_PATH(raw, 'event_type')) = 'VARCHAR', GET_PATH(raw, 'event_type')::STRING, NULL) AS event_type,
      IFF(TYPEOF(GET_PATH(raw, 'entity_id')) = 'VARCHAR', GET_PATH(raw, 'entity_id')::STRING, NULL) AS entity_id,
      IFF(TYPEOF(GET_PATH(raw, 'op')) = 'VARCHAR', GET_PATH(raw, 'op')::STRING, NULL) AS op,
      IFF(TYPEOF(GET_PATH(raw, 'schema_version')) = 'INTEGER', GET_PATH(raw, 'schema_version')::NUMBER, NULL) AS schema_version,
      IFF(TYPEOF(GET_PATH(raw, 'sequence')) = 'INTEGER', GET_PATH(raw, 'sequence')::NUMBER, NULL) AS sequence,
      TRY_TO_TIMESTAMP_NTZ(IFF(REGEXP_LIKE(GET_PATH(raw, 'event_time')::STRING, '[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}[.][0-9]{3}Z'), GET_PATH(raw, 'event_time')::STRING, NULL), 'YYYY-MM-DD"T"HH24:MI:SS.FF3"Z"') AS event_time,
      TRY_TO_TIMESTAMP_NTZ(IFF(REGEXP_LIKE(GET_PATH(raw, 'emitted_at')::STRING, '[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}[.][0-9]{3}Z'), GET_PATH(raw, 'emitted_at')::STRING, NULL), 'YYYY-MM-DD"T"HH24:MI:SS.FF3"Z"') AS emitted_at,
      IFF(TYPEOF(GET_PATH(raw, 'payload.merchant_id')) = 'VARCHAR', GET_PATH(raw, 'payload.merchant_id')::STRING, NULL) AS merchant_id,
      IFF(TYPEOF(GET_PATH(raw, 'payload.name')) = 'VARCHAR', GET_PATH(raw, 'payload.name')::STRING, NULL) AS name,
      IFF(TYPEOF(GET_PATH(raw, 'payload.country')) = 'VARCHAR', GET_PATH(raw, 'payload.country')::STRING, NULL) AS country,
      IFF(TYPEOF(GET_PATH(raw, 'payload.vertical')) = 'VARCHAR', GET_PATH(raw, 'payload.vertical')::STRING, NULL) AS vertical,
      IFF(TYPEOF(GET_PATH(raw, 'payload.risk_status')) = 'VARCHAR', GET_PATH(raw, 'payload.risk_status')::STRING, NULL) AS risk_status,
      raw,
      source_file,
      source_row,
      loaded_at
    FROM {db}.BRONZE.ref_merchants_stream
  ),
  checked AS (
    SELECT *,
      CASE
        WHEN event_id IS NULL THEN 'missing_event_id'
        WHEN event_type IS NULL THEN 'missing_event_type'
        WHEN entity_id IS NULL THEN 'missing_entity_id'
        WHEN event_time IS NULL THEN 'bad_type_event_time'
        WHEN emitted_at IS NULL THEN 'bad_type_emitted_at'
        WHEN schema_version IS NULL THEN 'bad_type_schema_version'
        WHEN sequence IS NULL THEN 'bad_type_sequence'
        WHEN schema_version NOT IN (1, 2) THEN 'unknown_schema_version'
        WHEN event_type NOT IN ('merchant_deleted', 'merchant_upserted') THEN 'unknown_event_type'
        WHEN COALESCE(op, '') NOT IN ('upsert', 'delete') THEN 'bad_op'
        WHEN merchant_id IS NULL THEN 'missing_payload_merchant_id'
        WHEN op = 'upsert' AND name IS NULL THEN 'missing_payload_name'
        WHEN op = 'upsert' AND country IS NULL THEN 'missing_payload_country'
        WHEN op = 'upsert' AND risk_status IS NULL THEN 'missing_payload_risk_status'
        WHEN op = 'upsert' AND risk_status NOT IN ('low', 'medium', 'high') THEN 'bad_value_risk_status'
      END AS reject_reason
    FROM parsed
  )
  SELECT event_id, merchant_id, sequence, reject_reason, raw, source_file, source_row, loaded_at
  FROM checked
  WHERE reject_reason IS NOT NULL;

  MERGE INTO {db}.SILVER.silver_merchants_versions v
  USING (
    WITH parsed AS (
      SELECT
        IFF(TYPEOF(GET_PATH(raw, 'event_id')) = 'VARCHAR', GET_PATH(raw, 'event_id')::STRING, NULL) AS event_id,
        IFF(TYPEOF(GET_PATH(raw, 'event_type')) = 'VARCHAR', GET_PATH(raw, 'event_type')::STRING, NULL) AS event_type,
        IFF(TYPEOF(GET_PATH(raw, 'entity_id')) = 'VARCHAR', GET_PATH(raw, 'entity_id')::STRING, NULL) AS entity_id,
        IFF(TYPEOF(GET_PATH(raw, 'op')) = 'VARCHAR', GET_PATH(raw, 'op')::STRING, NULL) AS op,
        IFF(TYPEOF(GET_PATH(raw, 'schema_version')) = 'INTEGER', GET_PATH(raw, 'schema_version')::NUMBER, NULL) AS schema_version,
        IFF(TYPEOF(GET_PATH(raw, 'sequence')) = 'INTEGER', GET_PATH(raw, 'sequence')::NUMBER, NULL) AS sequence,
        TRY_TO_TIMESTAMP_NTZ(IFF(REGEXP_LIKE(GET_PATH(raw, 'event_time')::STRING, '[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}[.][0-9]{3}Z'), GET_PATH(raw, 'event_time')::STRING, NULL), 'YYYY-MM-DD"T"HH24:MI:SS.FF3"Z"') AS event_time,
        TRY_TO_TIMESTAMP_NTZ(IFF(REGEXP_LIKE(GET_PATH(raw, 'emitted_at')::STRING, '[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}[.][0-9]{3}Z'), GET_PATH(raw, 'emitted_at')::STRING, NULL), 'YYYY-MM-DD"T"HH24:MI:SS.FF3"Z"') AS emitted_at,
        IFF(TYPEOF(GET_PATH(raw, 'payload.merchant_id')) = 'VARCHAR', GET_PATH(raw, 'payload.merchant_id')::STRING, NULL) AS merchant_id,
        IFF(TYPEOF(GET_PATH(raw, 'payload.name')) = 'VARCHAR', GET_PATH(raw, 'payload.name')::STRING, NULL) AS name,
        IFF(TYPEOF(GET_PATH(raw, 'payload.country')) = 'VARCHAR', GET_PATH(raw, 'payload.country')::STRING, NULL) AS country,
        IFF(TYPEOF(GET_PATH(raw, 'payload.vertical')) = 'VARCHAR', GET_PATH(raw, 'payload.vertical')::STRING, NULL) AS vertical,
        IFF(TYPEOF(GET_PATH(raw, 'payload.risk_status')) = 'VARCHAR', GET_PATH(raw, 'payload.risk_status')::STRING, NULL) AS risk_status,
        raw,
        source_file,
        source_row,
        loaded_at
      FROM {db}.BRONZE.ref_merchants_stream
    ),
    checked AS (
      SELECT *,
        CASE
          WHEN event_id IS NULL THEN 'missing_event_id'
          WHEN event_type IS NULL THEN 'missing_event_type'
          WHEN entity_id IS NULL THEN 'missing_entity_id'
          WHEN event_time IS NULL THEN 'bad_type_event_time'
          WHEN emitted_at IS NULL THEN 'bad_type_emitted_at'
          WHEN schema_version IS NULL THEN 'bad_type_schema_version'
          WHEN sequence IS NULL THEN 'bad_type_sequence'
          WHEN schema_version NOT IN (1, 2) THEN 'unknown_schema_version'
          WHEN event_type NOT IN ('merchant_deleted', 'merchant_upserted') THEN 'unknown_event_type'
          WHEN COALESCE(op, '') NOT IN ('upsert', 'delete') THEN 'bad_op'
          WHEN merchant_id IS NULL THEN 'missing_payload_merchant_id'
          WHEN op = 'upsert' AND name IS NULL THEN 'missing_payload_name'
          WHEN op = 'upsert' AND country IS NULL THEN 'missing_payload_country'
          WHEN op = 'upsert' AND risk_status IS NULL THEN 'missing_payload_risk_status'
          WHEN op = 'upsert' AND risk_status NOT IN ('low', 'medium', 'high') THEN 'bad_value_risk_status'
        END AS reject_reason
      FROM parsed
    )
    SELECT merchant_id, sequence, event_id, op = 'delete' AS is_deleted, name, country, vertical, risk_status,
           event_time AS valid_from, loaded_at, source_file, source_row
    FROM checked
    WHERE reject_reason IS NULL
    QUALIFY ROW_NUMBER() OVER (PARTITION BY merchant_id, sequence ORDER BY loaded_at, source_file, source_row) = 1
  ) s
  ON v.merchant_id = s.merchant_id AND v.sequence = s.sequence
  WHEN NOT MATCHED THEN INSERT (merchant_id, sequence, event_id, is_deleted, name, country, vertical, risk_status, valid_from, loaded_at, source_file, source_row)
    VALUES (s.merchant_id, s.sequence, s.event_id, s.is_deleted, s.name, s.country, s.vertical, s.risk_status, s.valid_from, s.loaded_at, s.source_file, s.source_row);

  MERGE INTO {db}.SILVER.silver_merchants t
  USING (
    SELECT merchant_id, sequence, event_id, is_deleted, FIRST_VALUE(name) OVER (PARTITION BY merchant_id ORDER BY IFF(is_deleted, 1, 0), sequence DESC) AS name, FIRST_VALUE(country) OVER (PARTITION BY merchant_id ORDER BY IFF(is_deleted, 1, 0), sequence DESC) AS country, FIRST_VALUE(vertical) OVER (PARTITION BY merchant_id ORDER BY IFF(is_deleted, 1, 0), sequence DESC) AS vertical, FIRST_VALUE(risk_status) OVER (PARTITION BY merchant_id ORDER BY IFF(is_deleted, 1, 0), sequence DESC) AS risk_status, valid_from
    FROM {db}.SILVER.silver_merchants_versions
    QUALIFY ROW_NUMBER() OVER (PARTITION BY merchant_id ORDER BY sequence DESC) = 1
  ) s
  ON t.merchant_id = s.merchant_id
  WHEN MATCHED AND (t.last_sequence IS DISTINCT FROM s.sequence OR t.is_deleted IS DISTINCT FROM s.is_deleted OR t.name IS DISTINCT FROM s.name OR t.country IS DISTINCT FROM s.country OR t.vertical IS DISTINCT FROM s.vertical OR t.risk_status IS DISTINCT FROM s.risk_status) THEN UPDATE SET
      name = s.name,
      country = s.country,
      vertical = s.vertical,
      risk_status = s.risk_status,
      is_deleted = s.is_deleted,
      last_sequence = s.sequence,
      last_event_id = s.event_id,
      last_event_time = s.valid_from
  WHEN NOT MATCHED THEN INSERT (merchant_id, name, country, vertical, risk_status, is_deleted, last_sequence, last_event_id, last_event_time)
    VALUES (s.merchant_id, s.name, s.country, s.vertical, s.risk_status, s.is_deleted, s.sequence, s.event_id, s.valid_from);

  COMMIT;
  RETURN 'ok';
EXCEPTION
  WHEN OTHER THEN
    ROLLBACK;
    RAISE;
END;
$$;

-- Created suspended. The WHEN clause means an idle stream never wakes the warehouse.
CREATE OR REPLACE TASK {db}.OPS.MERGE_MERCHANTS_TASK
  WAREHOUSE = TRANSFORM_WH
  SCHEDULE = '5 MINUTE'
  WHEN SYSTEM$STREAM_HAS_DATA('{db}.BRONZE.ref_merchants_stream')
AS
  CALL {db}.OPS.MERGE_MERCHANTS();

