  ) s
  ON v.account_id = s.account_id AND v.sequence = s.sequence
  WHEN NOT MATCHED THEN INSERT (account_id, sequence, event_id, is_deleted, merchant_id, label, currency, fee_plan, payout_schedule, status, valid_from, loaded_at, source_file, source_row)
    VALUES (s.account_id, s.sequence, s.event_id, s.is_deleted, s.merchant_id, s.label, s.currency, s.fee_plan, s.payout_schedule, s.status, s.valid_from, s.loaded_at, s.source_file, s.source_row);

  MERGE INTO {db}.SILVER.silver_accounts t
  USING (
    SELECT account_id, sequence, event_id, is_deleted, FIRST_VALUE(merchant_id) OVER (PARTITION BY account_id ORDER BY IFF(is_deleted, 1, 0), sequence DESC) AS merchant_id, FIRST_VALUE(label) OVER (PARTITION BY account_id ORDER BY IFF(is_deleted, 1, 0), sequence DESC) AS label, FIRST_VALUE(currency) OVER (PARTITION BY account_id ORDER BY IFF(is_deleted, 1, 0), sequence DESC) AS currency, FIRST_VALUE(fee_plan) OVER (PARTITION BY account_id ORDER BY IFF(is_deleted, 1, 0), sequence DESC) AS fee_plan, FIRST_VALUE(payout_schedule) OVER (PARTITION BY account_id ORDER BY IFF(is_deleted, 1, 0), sequence DESC) AS payout_schedule, FIRST_VALUE(status) OVER (PARTITION BY account_id ORDER BY IFF(is_deleted, 1, 0), sequence DESC) AS status, valid_from
    FROM {db}.SILVER.silver_accounts_versions
    QUALIFY ROW_NUMBER() OVER (PARTITION BY account_id ORDER BY sequence DESC) = 1
  ) s
  ON t.account_id = s.account_id
  WHEN MATCHED AND (t.last_sequence IS DISTINCT FROM s.sequence OR t.is_deleted IS DISTINCT FROM s.is_deleted OR t.merchant_id IS DISTINCT FROM s.merchant_id OR t.label IS DISTINCT FROM s.label OR t.currency IS DISTINCT FROM s.currency OR t.fee_plan IS DISTINCT FROM s.fee_plan OR t.payout_schedule IS DISTINCT FROM s.payout_schedule OR t.status IS DISTINCT FROM s.status) THEN UPDATE SET
      merchant_id = s.merchant_id,
      label = s.label,
      currency = s.currency,
      fee_plan = s.fee_plan,
      payout_schedule = s.payout_schedule,
      status = s.status,
      is_deleted = s.is_deleted,
      last_sequence = s.sequence,
      last_event_id = s.event_id,
      last_event_time = s.valid_from
  WHEN NOT MATCHED THEN INSERT (account_id, merchant_id, label, currency, fee_plan, payout_schedule, status, is_deleted, last_sequence, last_event_id, last_event_time)
    VALUES (s.account_id, s.merchant_id, s.label, s.currency, s.fee_plan, s.payout_schedule, s.status, s.is_deleted, s.sequence, s.event_id, s.valid_from);

  COMMIT;
  RETURN 'ok';
EXCEPTION
  WHEN OTHER THEN
    ROLLBACK;
    RAISE;
END;
$$;

-- Created suspended. The WHEN clause means an idle stream never wakes the warehouse.
CREATE OR REPLACE TASK {db}.OPS.MERGE_ACCOUNTS_TASK
  WAREHOUSE = TRANSFORM_WH
  SCHEDULE = '5 MINUTE'
  WHEN SYSTEM$STREAM_HAS_DATA('{db}.BRONZE.ref_accounts_stream')
AS
  CALL {db}.OPS.MERGE_ACCOUNTS();
